+    if fault() == Fault::Semantic(row) { return Err(Error::RowOrder { expected: row, actual: row + 1 }); }
+    let value = transcript.semantic_validated(record)?;
+    event(Event::SemanticDone(row, transcript.state(), transcript.next_row()));
